<script setup>
import {computed,ref,onMounted,onUnmounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useClinicContextStore} from '../../stores/clinicContext';import {useAppointmentStore} from '../../stores/appointments';import {calendarRange,addDays,moveMonth,formatDate} from '../../utils/appointmentDates';import AppointmentTimeline from '../../components/appointments/AppointmentTimeline.vue';import AppointmentMonthView from '../../components/appointments/AppointmentMonthView.vue';import AppointmentScheduleView from '../../components/appointments/AppointmentScheduleView.vue';import TodayPanel from '../../components/appointments/TodayPanel.vue';import AppointmentDrawer from '../../components/appointments/AppointmentDrawer.vue';import FormErrors from '../../components/ui/FormErrors.vue';
const route=useRoute(),router=useRouter(),context=useClinicContextStore(),store=useAppointmentStore();const compact=ref(false),showToday=ref(false),search=ref(route.query.search||''),now=ref(new Date());let timer,interval;const ownPath=route.path;
const view=computed(()=>['day','week','month','schedule'].includes(route.query.view)?route.query.view:window.innerWidth<650?'day':'week');
const date=computed(()=>/^\d{4}-\d{2}-\d{2}$/.test(route.query.date||'')&&!Number.isNaN(Date.parse(route.query.date))?route.query.date:context.data.today);
const range=computed(()=>view.value==='schedule'?{start:route.query.start||calendarRange(date.value,'week').start,end:route.query.end||calendarRange(date.value,'week').end}:calendarRange(date.value,view.value));
const filters=computed(()=>({branch_id:route.query.branch_id||String(context.data.branch.id),doctor_id:route.query.doctor_id||'',status:route.query.status||'',appointment_type_id:route.query.appointment_type_id||'',search:route.query.search||'',...range.value,page:route.query.page||1}));
const title=computed(()=>view.value==='month'?formatDate(date.value,{month:'long',year:'numeric'}):view.value==='day'?formatDate(date.value,{weekday:'long',month:'short',day:'numeric'}):`${formatDate(range.value.start,{month:'short',day:'numeric'})} – ${formatDate(range.value.end)}`);
const nowTime=computed(()=>now.value.toLocaleTimeString('en-GB',{timeZone:context.data.clinic.timezone,hour:'2-digit',minute:'2-digit'}));
function change(values){const q={...route.query,...values,page:values.page||1};Object.keys(q).forEach(k=>{if(q[k]===''||q[k]==null)delete q[k];});router.push({path:route.path,query:q});}
function find(){clearTimeout(timer);const term=search.value;timer=setTimeout(()=>{timer=null;change({search:term});},350);}
function move(delta){const next=view.value==='month'?moveMonth(date.value,delta):addDays(date.value,delta*(view.value==='day'?1:7));change({date:next,start:'',end:''});}
function open(a){router.push({path:`/app/appointments/${a.id}`,query:route.query});}
function create(values={}){router.push({path:'/app/appointments/create',query:{branch_id:filters.value.branch_id,doctor_id:filters.value.doctor_id,date:date.value,...values}});}
const load=()=>store.load(filters.value,view.value);
watch(()=>route.query,()=>{if(route.path!==ownPath)return;if(!timer)search.value=route.query.search||'';load();});
onMounted(()=>{load();interval=setInterval(()=>{now.value=new Date();},30000);});onUnmounted(()=>{clearTimeout(timer);clearInterval(interval);store.generation++;});
</script>
<template><div class="patient-page-header"><div><p class="patient-breadcrumb"><RouterLink to="/app/dashboard">Dashboard</RouterLink><span>/</span>Appointments</p><h1>Appointments</h1><p>Schedule and manage patient appointments.</p></div><button v-if="context.can('appointments.create')" class="btn" @click="create()">＋ New Appointment</button></div><p v-if="store.notice" class="clinic-trial" role="status">{{store.notice}}<button class="ml-auto" aria-label="Dismiss notification" @click="store.notice=''">×</button></p><div class="appointment-top-toolbar"><select :value="filters.branch_id" aria-label="Appointment branch" @change="change({branch_id:$event.target.value,doctor_id:''})"><option v-for="b in context.data.branches" :key="b.id" :value="b.id">{{b.name}}</option></select><input v-model="search" type="search" aria-label="Search appointments" placeholder="Search patients, doctors or appointment ID…" @input="find"><label class="appointment-compact"><input v-model="compact" type="checkbox">Compact mode</label><select :value="filters.doctor_id" aria-label="Doctor filter" @change="change({doctor_id:$event.target.value})"><option value="">All Doctors</option><option v-for="d in store.options?.doctors" :key="d.id" :value="d.id">{{d.full_name}}</option></select></div><FormErrors :error="store.error"/><div class="appointment-workspace"><section class="clinic-panel appointment-main"><div class="appointment-calendar-toolbar"><div><button class="btn-secondary" aria-label="Previous period" @click="move(-1)">‹</button><button class="btn-secondary" aria-label="Next period" @click="move(1)">›</button><strong>{{title}}</strong></div><div><button class="btn-secondary" @click="change({date:context.data.today,start:'',end:''})">Today</button><button v-for="v in ['day','week','month','schedule']" :key="v" :class="view===v?'btn':'btn-secondary'" :aria-pressed="view===v" @click="change({view:v})">{{v[0].toUpperCase()+v.slice(1)}}</button></div></div><div v-if="view==='schedule'" class="appointment-date-range"><label class="field">From<input type="date" :value="range.start" @change="change({start:$event.target.value})"></label><label class="field">To<input type="date" :value="range.end" :min="range.start" @change="change({end:$event.target.value})"></label></div><div v-if="store.busy" class="appointment-loading" role="status">Loading appointments…</div><div v-else-if="store.error" class="empty-state"><button class="btn" @click="load">Try again</button></div><template v-else><p v-if="!store.rows.length&&view!=='schedule'" class="appointment-empty-message">{{filters.search?'No appointments match your search.':'No appointments scheduled for this period.'}}</p><AppointmentMonthView v-if="view==='month'" :date="date" :today="context.data.today" :counts="store.counts" @day="change({date:$event,view:'day'})"/><AppointmentScheduleView v-else-if="view==='schedule'" :rows="store.rows" :meta="store.meta" @page="change({page:$event})"/><AppointmentTimeline v-else :date="date" :view="view" :today="context.data.today" :now-time="nowTime" :compact="compact" @open="open" @create="create"/></template><footer class="appointment-calendar-footer"><span>{{context.data.clinic.timezone}} · {{nowTime}}</span><span>Week: Saturday – Friday</span><span>Shaded slots are outside working hours</span></footer></section><div class="appointment-today-wrap" :class="{'is-expanded':showToday}"><button class="btn-secondary appointment-today-toggle" :aria-expanded="showToday" @click="showToday=!showToday">{{showToday?'Hide':'Show'}} today's appointments</button><TodayPanel :today="context.data.today" :filters="filters" @filter="change" @open="open" @page="store.todayPage(filters,$event)"/></div></div><AppointmentDrawer v-if="route.params.id" :key="route.params.id" :id="Number(route.params.id)" @changed="load"/></template>
